const item = $input.first().json;
const src = (item.body && typeof item.body === 'object') ? item.body : item;
const message = String(src.message || '').trim();
const customerId = String(src.customer_id || '').trim();
const errors = [];
if (!message) errors.push('message is required');
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(customerId)) errors.push('customer_id must be the customer UUID from the customers table');
const toText = v => (v === undefined || v === null) ? '' : (typeof v === 'string' ? v : JSON.stringify(v));
const base = String(item.supabase_url || '').replace(/\/+$/, '');
const m = message.match(/\bORD-\d{3,}\b/i);
const orderNumber = m ? m[0].toUpperCase() : null;
const select = 'id,order_number,status,total,currency,items,tracking_number,placed_at,shipped_at,delivered_at';
const ordersUrl = base + '/rest/v1/orders?customer_id=eq.' + customerId + (orderNumber ? '&order_number=eq.' + orderNumber : '&order=placed_at.desc&limit=5') + '&select=' + select;
return [{ json: {
  valid: errors.length === 0, errors,
  customer_id: customerId, message,
  intent: toText(src.intent), memory: toText(src.memory), context: toText(src.context),
  order_number_mentioned: orderNumber, orders_url: ordersUrl,
  supabase_url: base, llm_model: item.llm_model
} }];

const ctx = $('Normalize Input').first().json;
const orders = $input.all().map(i => i.json).filter(o => o && o.order_number);
const orderText = orders.map(o => [
  'Order: ' + o.order_number, 'Status: ' + o.status, 'Total: ' + o.total + ' ' + o.currency,
  'Items: ' + JSON.stringify(o.items), 'Tracking number: ' + (o.tracking_number || 'NOT AVAILABLE'),
  'Placed: ' + (o.placed_at || 'NOT AVAILABLE'), 'Shipped: ' + (o.shipped_at || 'NOT AVAILABLE'), 'Delivered: ' + (o.delivered_at || 'NOT AVAILABLE')
].join('\n')).join('\n---\n');
const evidence = orders.map(o => ({ order_number: o.order_number, status: o.status, total: o.total, currency: o.currency, items: o.items, tracking_number: o.tracking_number, placed_at: o.placed_at, shipped_at: o.shipped_at, delivered_at: o.delivered_at }));
const orderIds = {};
orders.forEach(o => { orderIds[o.order_number] = o.id; });
const user = 'ORDER DATA (this customer only):\n' + (orderText || 'NONE (no matching order found on this account)') +
  '\n\nCUSTOMER MEMORY (background only):\n' + (ctx.memory || 'none') +
  '\n\nCUSTOMER MESSAGE:\n' + ctx.message +
  (ctx.context ? '\n\nSUPERVISOR REVIEW NOTE (a previous answer was rejected; answer again using ONLY the order data above and remove any unsupported claim):\n' + ctx.context : '');
return [{ json: { customer_id: ctx.customer_id, message: ctx.message, supabase_url: ctx.supabase_url, llm_model: ctx.llm_model, evidence, order_ids: orderIds, system_prompt: "You are the Support Agent of a small business. Use ONLY the ORDER DATA provided; it contains only this customer's own orders. Rules: (1) Never invent order status, tracking numbers, delivery dates, refund status or any other fact. If the data does not contain it, say you do not have that verified information. (2) If the customer asks about an order and no matching order is in the data, say you could not find that order on their account and ask them to check the order number. Do not guess. (3) Refunds: no refund policy is configured. Never approve, deny, promise, or estimate the time or amount of a refund, and never state eligibility. For a refund request you may only say the request will be recorded and passed to the team for review. Use request_type refund_request only when the customer names an order that is present in ORDER DATA; otherwise ask for the order number and use request_type general. (4) Complaints: respond with empathy, do not promise compensation, and say the complaint will be recorded and passed to the team; request_type complaint. (5) If the customer asks for a human, request_type human_handoff. (6) CUSTOMER MEMORY is background only, never a source of order facts. (7) If the customer only asks about or refers to an earlier request and does not ask for a new action, do NOT use refund_request or complaint; use general, and say what the earlier request was only if it appears in CUSTOMER MEMORY. (8) Reply in the same language as the customer message. Return ONLY a JSON object: {\"response\": string, \"confidence\": number between 0 and 1, \"request_type\": one of order_status, complaint, refund_request, human_handoff, general, \"order_number\": string or null (the order this request is about, only if it is present in ORDER DATA), \"summary\": one short English sentence describing the customer's issue, \"needs_human\": boolean (true for complaint, refund_request and human_handoff), \"handoff_reason\": string or null}. confidence reflects how well ORDER DATA supports your answer.", user_prompt: user } }];

const b = $('Build Context').first().json;
const ai = $input.first().json;
let content = ai.choices[0].message.content;
content = String(content).replace(/```json|```/g, '').trim();
const p = JSON.parse(content);
const allowed = ['order_status', 'complaint', 'refund_request', 'human_handoff', 'general'];
let type = allowed.includes(p.request_type) ? p.request_type : 'general';
let response = String(p.response || '').trim();
if (!response) throw new Error('LLM returned an empty response');
let confidence = Math.max(0, Math.min(1, Number(p.confidence) || 0));
let orderNumber = p.order_number ? String(p.order_number).toUpperCase() : null;
const orderId = orderNumber && b.order_ids[orderNumber] ? b.order_ids[orderNumber] : null;
if (!orderId) orderNumber = null;
if (type === 'refund_request' && !orderId) {
  type = 'general';
  response = "Please share your order number (for example ORD-1001) so we can record your request. / অনুগ্রহ করে আপনার অর্ডার নম্বর (যেমন ORD-1001) জানান, তাহলে আমরা আপনার অনুরোধ নথিভুক্ত করতে পারব।";
  confidence = Math.min(confidence, 0.6);
}
const needsHuman = ['complaint', 'refund_request', 'human_handoff'].includes(type);
const createTicket = needsHuman;
const ticket = createTicket ? {
  customer_id: b.customer_id, order_id: orderId, type,
  summary: String(p.summary || '').slice(0, 500), message: String(b.message).slice(0, 2000),
  status: type === 'refund_request' ? 'pending_human_review' : 'open'
} : null;
const NONE = '00000000-0000-0000-0000-000000000000';
const dupUrl = createTicket ? (b.supabase_url + '/rest/v1/support_tickets?customer_id=eq.' + b.customer_id + '&type=eq.' + type + '&order_id=eq.' + (orderId || NONE) + '&status=in.(open,pending_human_review)&order=created_at.desc&limit=1&select=id,status') : null;
return [{ json: { dup_url: dupUrl, create_ticket: createTicket, ticket_payload: ticket, response, confidence, request_type: type, order_number: orderNumber, needs_human: needsHuman, handoff_reason: needsHuman ? String(p.handoff_reason || type).slice(0, 300) : null, supabase_url: b.supabase_url } }];

const p = $('Parse & Decide').first().json;
let ticket = null, dup = false;
try { const t = $('Insert Ticket').first().json; if (t && t.id) ticket = t; } catch (e) {}
if (!ticket) { try { const t = $('Check Duplicate Ticket').first().json; if (t && t.id) { ticket = t; dup = true; } } catch (e) {} }
const ref = ticket ? String(ticket.id).slice(0, 8).toUpperCase() : null;
return [{ json: { success: true, response: p.response + (ref ? '\n\nReference: ' + ref + (dup ? ' (existing request, no new ticket was created)' : '') : ''), confidence: p.confidence,
  data: { request_type: p.request_type, order_number: p.order_number, ticket_id: ticket ? ticket.id : null, ticket_reference: ref, ticket_status: ticket ? ticket.status : null, ticket_duplicate: dup, handoff_reason: p.handoff_reason, evidence: $('Build Context').first().json.evidence },
  needs_human: p.needs_human, error: null, agent: 'support' } }];

const j = $input.first().json || {};
const e = j.error || j;
const msg = String(e.message || e.description || (typeof e === 'string' ? e : JSON.stringify(e))).slice(0, 500);
return [{ json: { success: false, response: null, confidence: 0, data: {}, needs_human: true, error: 'support_agent_failed: ' + msg, agent: 'support' } }];
